def flatten(d: dict) -> dict:
    result = {}
    for key, value in d.items():
        new_key = f"{key}" if isinstance(key, str) else str(key)
        if isinstance(value, dict):
            prefix = f"{new_key}." if new_key != "" else ""
            flattened = flatten(value)
            result.update({f"{prefix}{k}": v for k, v in flattened.items()})
        else:
            result[new_key] = value
    return result
